/* az_gpu_ref.c - the CPU reference the GPU is compared with.
 *
 * It is the same text the device translation unit (az_gpu_dev.c) compiles:
 * az_gpu_dev_srcs.h, generated by CMake, includes core/az_rng.c and
 * core/az_brain.c (or their stubs). Here the host compiler builds it with
 * the flags of az_core, and the functions keep their external names:
 * az_philox4x32, az_philox4x32_n, az_dense_step_c, az_dense_develop.
 *
 * Linking this instead of az_core keeps the GPU component buildable while
 * other modules are in flux. Functions of the brain file that need the rest
 * of the core (world code) are dropped by the linker (--gc-sections) unless
 * a test reaches them.
 */
#include "az_abi.h"
#include "az_dense.h"

/* az_world.c is not linked: the two helpers the core expects from it */
void az_memset(void *dst, int v, size_t n)
{
    u8 *d = (u8 *)dst;
    for (size_t i = 0; i < n; i++) d[i] = (u8)v;
}
void az_memcpy(void *dst, const void *src, size_t n)
{
    u8 *d = (u8 *)dst;
    const u8 *s = (const u8 *)src;
    for (size_t i = 0; i < n; i++) d[i] = s[i];
}
/* az_ledger.c is not linked: az_clade_assign in core/az_brain.c is unreachable
 * from test_gpu/az_gpubench, but COFF ld resolves before --gc-sections drops it. */
void az_emit(AzWorld *w, u32 worker, u32 kind, u32 aux, u64 a, u64 b, i64 v)
{
    (void)w; (void)worker; (void)kind; (void)aux; (void)a; (void)b; (void)v;
}

#include "az_gpu_dev_srcs.h"   /* #include "<...>/az_rng.c" and "<...>/az_brain.c" */
